import {createRequire} from 'node:module';
const require=createRequire(new URL('../work/CodeLab/package.json',import.meta.url));
const {newQuickJSWASMModuleFromVariant}=require('quickjs-emscripten-core');
const entrada=require('@jitl/quickjs-wasmfile-release-sync');
const inicio=performance.now();
const modulo=await newQuickJSWASMModuleFromVariant(entrada.default??entrada);
const ambiente=modulo.newRuntime();
ambiente.setMemoryLimit(4*1024*1024);
ambiente.setMaxStackSize(256*1024);
const limite=performance.now()+1200;
ambiente.setInterruptHandler(()=>performance.now()>limite);
const contexto=ambiente.newContext();
const antes=performance.now(),cpu=process.cpuUsage();
const resultado=contexto.evalCode('const values=[]; while(true) values.push(new Array(100000).fill(123));');
console.log(JSON.stringify({fase:'avaliacao',paredeMs:Math.round(performance.now()-antes),cpuMicros:process.cpuUsage(cpu),erro:resultado.error?contexto.dump(resultado.error):null}));
if(resultado.error)resultado.error.dispose();else resultado.value.dispose();
const limpar=performance.now();
contexto.dispose();ambiente.dispose();
console.log(JSON.stringify({fase:'limpeza',paredeMs:Math.round(performance.now()-limpar),totalMs:Math.round(performance.now()-inicio),viteCarregado:false}));

import {test,expect} from '../work/CodeLab/node_modules/@playwright/test/index.mjs';
async function escrever(pagina,codigo){
 const campo=pagina.getByRole('textbox',{name:'É aqui que você escreve seu código'});
 await campo.focus();await pagina.keyboard.press('Control+a');
 await campo.evaluate((elemento,texto)=>{const dados=new DataTransfer();dados.setData('text/plain',texto);elemento.dispatchEvent(new ClipboardEvent('paste',{clipboardData:dados,bubbles:true,cancelable:true}));},codigo);
}
test('o limite externo encerra a alocação em vetor e permite executar novamente',async({page:pagina})=>{
 await pagina.emulateMedia({reducedMotion:'reduce'});
 await pagina.goto('/#/missao/primeira-luz');
 await expect(pagina.locator('.monaco-editor')).toBeVisible();
 await escrever(pagina,'const values=[]; while(true) values.push(new Array(100000).fill(123));');
 await pagina.locator('#run').click();
 await expect(pagina.locator('#result')).toContainText(/memória|tempo limite|tempo demais/,{timeout:15000});
 await escrever(pagina,'acender();');await pagina.locator('#run').click();
 await expect(pagina.locator('#result')).toContainText('Você fez o mundo responder.',{timeout:15000});
});
